def run_commands(cmds):
    book = {}
    out = []
    for cmd in cmds:
        parts = cmd.split()
        action = parts[0]
        if action == "add":
            name, number = parts[1], parts[2]
            out.append(("수정: " if name in book else "추가: ") + name)
            book[name] = number
        elif action == "find":
            out.append(book.get(parts[1], "없음"))
        elif action == "del":
            if parts[1] in book:
                del book[parts[1]]
                out.append("삭제: " + parts[1])
            else:
                out.append("없음")
        elif action == "list":
            out.append(",".join(sorted(book)) if book else "비어 있음")
    return out

